@push('scripts')
<script>
$(function(){
 const table=$('#finishedTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.finished-goods.dt')),data:d=>{d.from_date=$('#finishedFrom').val();d.to_date=$('#finishedTo').val()}},columns:[{data:'DT_RowIndex',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false,className:'text-nowrap'},{data:'finished_goods_number',name:'finished_goods_number'},{data:'date',name:'processed_at',render:d=>d?new Date(d+'T00:00:00').toLocaleDateString():''},{data:'style',orderable:false,searchable:false},{data:'item_code',orderable:false,searchable:false},{data:'item_name',orderable:false,searchable:false},{data:'input_quantity',className:'text-end'},{data:'good_quantity',className:'text-end'},{data:'mo',orderable:false,searchable:false},{data:'po_buyer',orderable:false,searchable:false},{data:'color',name:'productionOrder.outputProduct.color'},{data:'size',name:'productionOrder.outputProduct.size'},{data:'order_quantity',name:'productionOrder.planned_quantity',className:'text-end'}],order:[[3,'desc']],drawCallback:()=>window.feather&&feather.replace()});
 $('#finishedFilter').on('click',()=>table.ajax.reload());$('#finishedExport').on('click',function(e){e.preventDefault();const q=new URLSearchParams();if($('#finishedFrom').val())q.set('from_date',$('#finishedFrom').val());if($('#finishedTo').val())q.set('to_date',$('#finishedTo').val());location.href=this.href+'?'+q.toString()});
 $(document).on('click','.js-delete-finished',function(){const id=$(this).data('id');Swal.fire({icon:'warning',title:@json(__('ui.common.confirm_delete')),showCancelButton:true,confirmButtonText:@json(__('ui.common.delete')),cancelButtonText:@json(__('ui.common.cancel'))}).then(r=>{if(r.isConfirmed)$.ajax({url:@json(route('super.finished-goods.destroy',['entry'=>'__ID__'])).replace('__ID__',id),method:'DELETE',data:{_token:@json(csrf_token())}}).done(x=>{table.ajax.reload(null,false);Swal.fire({icon:'success',text:x.message})}).fail(x=>Swal.fire({icon:'error',text:x.responseJSON?.message||'Error'}))})});
});
</script>
